const items = $input.all();
const now = new Date();
const TWO_HOURS_MS = 2 * 60 * 60 * 1000; // 7200000 ms

const expiredSessions = [];
const activeSessions = [];

for (const item of items) {
  const keys = item.json;

  if (!keys || typeof keys !== 'object') {
    continue;
  }

  for (const [key, value] of Object.entries(keys)) {
    if (!key.startsWith('leviathan:demo:')) {
      continue;
    }

    try {
      const sessionData = typeof value === 'string' ? JSON.parse(value) : value;
      const lastUpdate = new Date(sessionData.last_update_ts);
      const age = now - lastUpdate;

      if (age > TWO_HOURS_MS) {
        expiredSessions.push({
          key: key,
          demo_session_id: sessionData.demo_session_id,
          last_update_ts: sessionData.last_update_ts,
          age_hours: (age / (1000 * 60 * 60)).toFixed(2)
        });
      } else {
        activeSessions.push({
          key: key,
          demo_session_id: sessionData.demo_session_id,
          status: sessionData.status,
          age_minutes: (age / (1000 * 60)).toFixed(2)
        });
      }
    } catch (e) {
      expiredSessions.push({
        key: key,
        error: 'Could not parse session data',
        raw: String(value).substring(0, 100)
      });
    }
  }
}

return [{
  json: {
    timestamp: now.toISOString(),
    summary: {
      total_found: expiredSessions.length + activeSessions.length,
      expired_count: expiredSessions.length,
      active_count: activeSessions.length
    },
    expired_sessions: expiredSessions,
    active_sessions: activeSessions
  }
}];

const items = $input.all();
const expiredSessions = items[0].json.expired_sessions || [];

return expiredSessions.map(session => ({
  json: {
    key: session.key,
    demo_session_id: session.demo_session_id
  }
}));

const items = $input.all();
const deletedCount = items.length;

console.log(`[Leviathan Cleanup] Deleted ${deletedCount} expired demo sessions at ${new Date().toISOString()}`);

return [{
  json: {
    cleanup_completed: true,
    deleted_count: deletedCount,
    timestamp: new Date().toISOString()
  }
}];

